import axios from "axios";

const BASE_URL = "http://127.0.0.1:8001";

export const grayScaleRequest = (data) => axios.post(`${BASE_URL}/grayScale/`, data).then((res) => res.data);
export const binaryRequest = (data) => axios.post(`${BASE_URL}/binaryDonusum/`, data).then((res) => res.data);
export const cropImageRequest = (data) => axios.post(`${BASE_URL}/cropImage/`, data).then((res) => res.data);
export const rotateRequest = (data) => axios.post(`${BASE_URL}/rotate/`, data).then((res) => res.data);
export const zoomInRequest = (data) => axios.post(`${BASE_URL}/zoomIn/`, data).then((res) => res.data);

export const edgeDetectionRequest = (data) => axios.post(`${BASE_URL}/edgeDetection/`, data).then((res) => res.data);
export const histogramStretchRequest = (data) => axios.post(`${BASE_URL}/histogramStretch/`, data).then((res) => res.data);
export const arithmeticOperationsRequest = (data) => axios.post(`${BASE_URL}/arithmetic/`, data).then((res) => res.data);
export const morphologyRequest = (data) => axios.post(`${BASE_URL}/morphology/`, data).then((res) => res.data);
export const motionBlurRequest = (data) => axios.post(`${BASE_URL}/motionBlur/`, data).then((res) => res.data);
export const colorSpaceConversionRequest = (data) => axios.post(`${BASE_URL}/colorSpace/`, data).then((res) => res.data);
export const convolutionRequest = (data) => axios.post(`${BASE_URL}/convolution/`, data).then((res) => res.data);
export const contrastReductionRequest = (data) => axios.post(`${BASE_URL}/contrast/`, data).then((res) => res.data);
export const doubleThresholdRequest = (data) => axios.post(`${BASE_URL}/doubleThreshold/`, data).then((res) => res.data);
export const gurultuEklemeRequest = (data) => axios.post(`${BASE_URL}/saltPepperNoise/`, data).then((res) => res.data);
export const gurultuTemizlemeRequest = (data) => axios.post(`${BASE_URL}/noiseRemoval/`, data).then((res) => res.data);
